#pragma once
#include "../../support.hpp"
#include "../../shared/compare.hpp"
namespace algs {
template<class T>class SkipList{struct Node{std::optional<T>value;std::vector<std::shared_ptr<Node>>next;Node(std::optional<T>v,int level):value(v),next(level){}};Comparator<T>compare;int maxLevel,level=1,length=0;double probability;std::shared_ptr<Node>head;std::vector<std::shared_ptr<Node>>predecessors(const T&v)const{std::vector<std::shared_ptr<Node>>update(maxLevel);auto n=head;for(int i=level-1;i>=0;--i){while(n->next[i]&&compare(*n->next[i]->value,v)<0)n=n->next[i];update[i]=n;}return update;}public:explicit SkipList(Comparator<T>c=defaultCompare<T>,int max=32,double p=0.5):compare(c),maxLevel(max),probability(p),head(std::make_shared<Node>(std::nullopt,max)){}int size()const{return length;}bool has(const T&v)const{auto n=predecessors(v)[0]->next[0];return n&&compare(*n->value,v)==0;}bool insert(T v){auto u=predecessors(v);auto n=u[0]->next[0];if(n&&!compare(*n->value,v))return false;int l=1;while(l<maxLevel&&random()<probability)++l;if(l>level){for(int i=level;i<l;++i)u[i]=head;level=l;}n=std::make_shared<Node>(v,l);for(int i=0;i<l;++i){n->next[i]=u[i]->next[i];u[i]->next[i]=n;}++length;return true;}bool erase(const T&v){auto u=predecessors(v);auto n=u[0]->next[0];if(!n||compare(*n->value,v))return false;for(int i=0;i<level&&u[i]->next[i]==n;++i)u[i]->next[i]=n->next[i];while(level>1&&!head->next[level-1])--level;--length;return true;}std::vector<T>toArray()const{std::vector<T>r;for(auto n=head->next[0];n;n=n->next[0])r.push_back(*n->value);return r;}};
}
